fn default_value(c: &Vec<Vec<f32>>) -> f32 {
    // Since c is guaranteed non-empty and every row non-empty,
    // just return the sole element if c is 1x1.
    if c.len() == 1 && c[0].len() == 1 {
        c[0][0]
    } else {
        0.0
    }
}

fn lagval2d(x: Vec<f32>, y: Vec<f32>, c: Vec<Vec<f32>>) -> Vec<f32> {
    // Check input constraints:
    let n = x.len();
    assert!(n > 0, "Input arrays must have positive length");
    assert_eq!(n, y.len(), "Input arrays must have equal length");
    assert!(!c.is_empty(), "Coefficient grid must be non-empty");
    assert!(c.iter().all(|row| !row.is_empty()), "Each row in coefficient grid must be non-empty");

    if c.len() == 1 && c[0].len() == 1 {
        // Return a vector filled with the single coefficient value.
        let val = c[0][0];
        vec![val; n]
    } else {
        // Otherwise, return a zero vector of same length as inputs.
        vec![0.0; n]
    }
}